const catalog = {
  oats:{price:3.28,unit:'42 oz canister',category:'Pantry'},banana:{price:1.47,unit:'bunch',category:'Produce'},cinnamon:{price:1.18,unit:'jar',category:'Pantry'},eggs:{price:3.12,unit:'dozen',category:'Dairy & eggs'},tortillas:{price:2.24,unit:'10 count',category:'Bakery'},'black beans':{price:.88,unit:'15 oz can',category:'Pantry'},tomato:{price:1.48,unit:'lb',category:'Produce'},bread:{price:1.98,unit:'loaf',category:'Bakery'},'peanut butter':{price:2.18,unit:'jar',category:'Pantry'},yogurt:{price:3.64,unit:'32 oz tub',category:'Dairy & eggs'},'frozen berries':{price:3.48,unit:'12 oz bag',category:'Frozen'},rice:{price:3.34,unit:'5 lb bag',category:'Pantry'},lentils:{price:1.62,unit:'1 lb bag',category:'Pantry'},'canned tomatoes':{price:.96,unit:'15 oz can',category:'Pantry'},onion:{price:2.48,unit:'3 lb bag',category:'Produce'},chickpeas:{price:.86,unit:'15 oz can',category:'Pantry'},lettuce:{price:1.88,unit:'head',category:'Produce'},chicken:{price:7.42,unit:'3 lb pack',category:'Meat'},'frozen vegetables':{price:1.16,unit:'12 oz bag',category:'Frozen'},'soy sauce':{price:1.72,unit:'bottle',category:'Pantry'},pasta:{price:1.18,unit:'1 lb box',category:'Pantry'},'pasta sauce':{price:1.68,unit:'24 oz jar',category:'Pantry'},potatoes:{price:3.24,unit:'5 lb bag',category:'Produce'},'sweet potatoes':{price:2.46,unit:'3 lb bag',category:'Produce'},salsa:{price:2.18,unit:'jar',category:'Pantry'},tuna:{price:1.08,unit:'5 oz can',category:'Pantry'},cheese:{price:2.22,unit:'8 oz bag',category:'Dairy & eggs'},apples:{price:3.48,unit:'3 lb bag',category:'Produce'},popcorn:{price:2.38,unit:'6 pack',category:'Snacks'}
};
const storeFactor={Walmart:1,Target:1.08,Kroger:1.04};

function checked(name){return $(`input[name="${name}"]:checked`).value}
function updateSummary(){const budget=$('#budget').value,store=checked('store'),mealCount=checked('meals'),time=checked('time');$('#summaryBudget').textContent=`$${budget} budget`;$('#summaryDetails').textContent=`${store} · ${mealCount} meals/day · up to ${time} min`;localStorage.setItem('cheapChefSettings',JSON.stringify({budget,store,mealCount,time,diet:$('#diet').value,allergy:$('#allergy').value,language:$('#language').value,equipment:$$('input[name=equipment]:checked').map(x=>x.value)}))}

function applyLanguage(lang){const t=translations[lang];document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';$$('[data-i18n]').forEach(el=>{const value=t[el.dataset.i18n];if(value)el.innerHTML=value});updateSummary()}

function allowedMeals(){const diet=$('#diet').value,allergy=$('#allergy').value,time=+checked('time'),equipment=$$('input[name=equipment]:checked').map(x=>x.value);return meals.filter(m=>m.time<=time&&(m.equipment.length===0||m.equipment.some(e=>equipment.includes(e)))&&(diet==='none'||m.tags.includes(diet))&&(allergy==='none'||m.tags.includes(`${allergy}-free`)))}

function buildPlan(){const available=allowedMeals();if(!available.length){alert('No meals match all of those choices. Add one piece of equipment or increase your prep time.');return null}const count=+checked('meals'),plan=[];for(let day=0;day<7;day++){const dayMeals=[];for(let slot=0;slot<count;slot++){dayMeals.push(available[(day*count+slot)%available.length])}plan.push(dayMeals)}return plan}

function consolidate(plan){const total={};plan.flat().forEach(meal=>Object.entries(meal.items).forEach(([item,qty])=>total[item]=(total[item]||0)+qty));return Object.entries(total).map(([name,amount])=>({name,amount, ...catalog[name],cost:catalog[name].price*storeFactor[checked('store')]}))}

function adjustToBudget(plan){const budget=+$('#budget').value;let list=consolidate(plan),total=list.reduce((sum,x)=>sum+x.cost,0);if(total<=budget)return {plan,list,total};const cheapest=allowedMeals().filter(m=>!m.items.chicken&&!m.items.tuna&&!m.items.cheese&&!m.items.yogurt);for(let d=6;d>=0&&total>budget;d--){for(let s=plan[d].length-1;s>=0&&total>budget;s--){plan[d][s]=cheapest[(d+s)%cheapest.length]||plan[d][s];list=consolidate(plan);total=list.reduce((sum,x)=>sum+x.cost,0)}}return {plan,list,total}}

function render(){const raw=buildPlan();if(!raw)return;const {plan,list,total}=adjustToBudget(raw);const lang=$('#language').value,names=mealNames[lang],t=translations[lang];$('#weekGrid').innerHTML=plan.map((day,i)=>`<article class="day-card"><h3>${names.days[i]}</h3>${day.map((m,j)=>`<div class="meal"><small>${names.types[j]}</small><p>${m.name}</p><span>${m.time} min</span><button class="cook-button" type="button" data-meal="${meals.indexOf(m)}">${t.cook} →</button></div>`).join('')}</article>`).join('');const grouped=Object.groupBy?Object.groupBy(list,x=>x.category):list.reduce((a,x)=>((a[x.category]||=[]).push(x),a),{});$('#groceryGrid').innerHTML=Object.entries(grouped).map(([category,items])=>`<section class="grocery-category"><h3>${category}</h3>${items.map(x=>`<label class="grocery-item"><input type="checkbox"><span>${x.name}<small>${x.unit}</small></span><b>$${x.cost.toFixed(2)}</b></label>`).join('')}</section>`).join('');$('#estimatedTotal').textContent=`$${total.toFixed(2)}`;const budget=+$('#budget').value,remaining=budget-total;$('#remainingText').textContent=remaining>=0?`$${remaining.toFixed(2)} left in your budget`:`$${Math.abs(remaining).toFixed(2)} over — try fewer meals or a larger budget`;$('#remainingText').style.color=remaining>=0?'var(--green)':'var(--orange)';$('#meterFill').style.width=`${Math.min(100,total/budget*100)}%`;$('#meterFill').style.background=remaining>=0?'var(--green)':'var(--orange)';$('#itemCount').textContent=list.length;$('#storeNote').textContent=`Estimated at ${checked('store')} · ${list.length} items`;$('#results').hidden=false;$('#results').scrollIntoView({behavior:'smooth',block:'start'})}

function openRecipe(index){const meal=meals[index],lang=$('#language').value,t=translations[lang];if(!meal)return;$('#recipeTitle').textContent=meal.name;const equipment=meal.equipment.length?meal.equipment.map(x=>t[x]||x).join(' / '):t.noEquipment;$('#recipeMeta').innerHTML=`<span>◷ ${meal.time} min</span><span>◉ ${equipment}</span>`;$('#recipeIngredients').innerHTML=Object.keys(meal.items).map(item=>`<li>${item}</li>`).join('');$('#recipeSteps').innerHTML=meal.steps.map(step=>`<li>${step}</li>`).join('');$('#recipeDialog').showModal()}

$('#budget').addEventListener('input',e=>{$('#budgetRange').value=Math.min(150,e.target.value);updateSummary()});$('#budgetRange').addEventListener('input',e=>{$('#budget').value=e.target.value;updateSummary()});$('#plannerForm').addEventListener('change',e=>{if(e.target.id==='language')applyLanguage(e.target.value);else updateSummary()});$('#plannerForm').addEventListener('submit',e=>{e.preventDefault();render()});$('#themeButton').addEventListener('click',()=>{document.body.classList.toggle('dark');$('#themeButton').textContent=document.body.classList.contains('dark')?'☾':'☼'});$('#printButton').addEventListener('click',()=>window.print());$('#weekGrid').addEventListener('click',e=>{const button=e.target.closest('[data-meal]');if(button)openRecipe(+button.dataset.meal)});$('#closeRecipe').addEventListener('click',()=>$('#recipeDialog').close());$('#recipeDialog').addEventListener('click',e=>{if(e.target===$('#recipeDialog'))$('#recipeDialog').close()});$$('[role=tab]').forEach(tab=>tab.addEventListener('click',()=>{$$('[role=tab]').forEach(t=>t.setAttribute('aria-selected','false'));tab.setAttribute('aria-selected','true');$('#mealPanel').hidden=tab.id!=='mealTab';$('#groceryPanel').hidden=tab.id!=='groceryTab'}));
updateSummary();
